//--- The indicator has one plotting


#property
 
indicator_plots
   1


//--- Graphical plotting number 1 will appear as candlesticks


#property
 
indicator_type1
   
DRAW_CANDLES


//--- Candlestick will be drawn in clrDodgerBlue


#property
 
indicator_color1
  
clrDodgerBlue


//--- 4 arrays for the indicator buffers


